INSERT INTO feature VALUES('grade-algebra','effects','Grade algebras',NULL,'partial','uncommon','mainstream languages','`std.grade` states `Grade`, an ordered semiring''s operations, and two models: `Usage`, the grades the tree writes, zero and one apart and each under many, and `Count`, the prelude''s binary naturals under sum and product. Each order is a function over closed data, so a path from it to `true` checks exactly when the order holds and the kernel replays it; an algebra over the native `Integer` decides nothing. A `Hom` names a map between two algebras, `collapse` counting''s to usage, and `covers` tests a grade of one against a need of another through it. The core''s grade positions do not read an algebra, and `Grade` states no law.',NULL,'library/std/src/grade.gandr corpus/ledger/features/grade-algebra.gandr corpus/model/effects/grade-algebra.gandr corpus/pathological/effects/grade-algebra.gandr','corpus/ledger/features/grade-algebra.gandr','#3392');
